class Solution {
public:
    int numberOfPaths(vector<vector<int>>& grid, int k) {
        const int MOD = 1e9 + 7;
        int m = grid.size();
        int n = grid[0].size();
        vector<vector<int>> dp(n, vector<int>(k, 0));

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j] % k;
                if (i == 0 && j == 0) {
                    dp[j].assign(k, 0);
                    dp[j][v] = 1;
                } else {
                    int tmp[50] = {};
                    for (int r = 0; r < k; r++) {
                        int src = ((r - v) % k + k) % k;
                        long long ways = 0;
                        if (i > 0) ways += dp[j][src];
                        if (j > 0) ways += dp[j - 1][src];
                        tmp[r] = ways % MOD;
                    }
                    for (int r = 0; r < k; r++) dp[j][r] = tmp[r];
                }
            }
        }

        return dp[n - 1][0];
    }
};
